def mob_level_of(v):
    """Monsterstufe (0-4) aus einer Einstellung; alte Ja/Nein-Werte werden übersetzt."""
    if v is True:
        return MOB_DEFAULT
    if v is False or v is None:
        return 0
    try:
        return max(0, min(len(MOB_LEVELS) - 1, int(v)))
    except (TypeError, ValueError):
        return MOB_DEFAULT
