ATT_NONE = (0, 0, 0)
_EFF_CACHE = {}


def att_valid(a):
    """a ist ein gültiger Aufsatz-Code (Liste/Tupel aus drei Indizes)? -> Tupel oder None."""
    if (isinstance(a, (list, tuple)) and len(a) == len(ATT_SLOTS)
            and all(isinstance(v, int) and not isinstance(v, bool) and 0 <= v < len(ATTACHMENTS[i])
                    for i, v in enumerate(a))):
        return tuple(a)
    return None


def att_name(si, v):
    """Anzeigename eines Aufsatzes (Platz si, Index v)."""
    n = ATTACHMENTS[si][v][0]
    return ATT_LONG.get(n, n)


ATT_BY_NAME = {ATTACHMENTS[si][v][0]: (si, v) for si in range(len(ATT_SLOTS)) for v in range(1, len(ATTACHMENTS[si]))}


def att_fits(wi):
    """Passt an diese Waffe ein Aufsatz? (Haupt- und Kleinwaffen ja, Spezialwaffen nein)"""
    return 0 <= wi < len(WEAPONS) and WEAPONS[wi].kind != "special" and WEAPONS[wi].name in GRIP_AT


def roll_attachment(rng, have=ATT_NONE):
    """Inhalt einer Aufsatz-Kiste -> (Platz, Index). have = Aufsätze der Waffe in der Hand (herausgerechnet)."""
    ch = {n: p for n, p in LOOT_ATT_TABLE.items() if n in ATT_BY_NAME and p > 0}
    left = {n: p for n, p in ch.items() if have[ATT_BY_NAME[n][0]] != ATT_BY_NAME[n][1]}
    pool = left or ch
    names = sorted(pool)
    return ATT_BY_NAME[rng.choices(names, weights=[pool[n] for n in names])[0]]


def eff_weapon(wi, att=None):
    """Waffe mit den Faktoren der Aufsätze (att = (Lauf, Magazin, Griff))."""
    base = WEAPONS[wi]
    att = att_valid(att)
    if att is None or att == ATT_NONE or base.kind == "special":
        return base
    key = (wi, att)
    w = _EFF_CACHE.get(key)
    if w is None:
        f = {}
        for i, v in enumerate(att):
            for k, m in ATTACHMENTS[i][v][2].items():
                f[k] = f.get(k, 1.0) * m
        w = dataclasses.replace(
            base,
            dmg=round(base.dmg * f.get("dmg", 1.0), 2),
            speed=base.speed * f.get("speed", 1.0),
            spread=base.spread * f.get("spread", 1.0),
            reload=round(base.reload * f.get("reload", 1.0), 2),
            kick=base.kick * f.get("kick", 1.0),
            kick_yaw=base.kick_yaw * f.get("kick_yaw", 1.0),
            ads_spread=base.ads_spread * f.get("ads_spread", 1.0),
            bloom=base.bloom * f.get("bloom", 1.0),
            mag=max(1, int(round(base.mag * f.get("mag", 1.0)))),
            max_reserve=max(1, int(round(base.max_reserve * f.get("reserve", 1.0)))))
        _EFF_CACHE[key] = w
    return w
