                      (0, 0.9, 0.0405, 0.022, 0.04, 0.016, _DK2), (0, 0.9, 0.0605, 0.008, 0.012, 0.0235, (0.06, 0.06, 0.07)),
                      (-0.0135, -0.1075, 0.0575, 0.004, 0.002, 0.006, _DOT), (0.0135, -0.1075, 0.0575, 0.004, 0.002, 0.006, _DOT),
