class UiSlider:
    """Waagerechter Schieberegler: Beschriftung links, Wert rechts, darunter Schiene mit Knopf.
    Gezogen wird mit der linken Maustaste (Game.ui_slider_press / slider_follow)."""
    def __init__(self, parent, spec, x0, x1, z, binned=True):
        # binned=False (Hauptmenü): Zeichenreihenfolge = Reihenfolge im Szenengraph, sonst läge der Hintergrund darüber
        self.sp, self.x0, self.x1, self.z, self.on = spec, x0, x1, z, False
        self.zt = z - 0.065
        self.root = parent.attachNewNode("uislider")

        def lay(n, sort):
            n.setTransparency(TransparencyAttrib.MAlpha)
            if binned:
                n.setBin("fixed", sort)
            n.setDepthTest(False)
            n.setDepthWrite(False)
            return n

        def card(a, b, c, d, sort):
            cm = CardMaker("uis")
            cm.setFrame(a, b, c, d)
            return lay(self.root.attachNewNode(cm.generate()), sort)

        zt = self.zt
        self.lab = OnscreenText(text=spec.label, pos=(x0, z), scale=0.05, parent=self.root,
                                fg=(0.86, 0.92, 1.0, 1) if spec.enabled else (0.5, 0.52, 0.55, 1),
                                shadow=(0, 0, 0, 0.9), align=TextNode.ALeft, mayChange=False)
        self.val = OnscreenText(text="", pos=(x1, z), scale=0.05, parent=self.root, fg=(1.0, 0.85, 0.2, 1),
                                shadow=(0, 0, 0, 0.9), align=TextNode.ARight, mayChange=True)
        if binned:
            self.lab.setBin("fixed", 95)
            self.val.setBin("fixed", 95)
        self.track = card(x0, x1, zt - 0.007, zt + 0.007, 92)
        self.track.setColor(0.16, 0.22, 0.30, 1)
        self.fill = card(0.0, 1.0, zt - 0.007, zt + 0.007, 93)
        self.fill.setPos(x0, 0, 0)
        self.knob = card(-0.022, 0.022, -0.022, 0.022, 94)
        self.knob.setR(45.0)
        self.refresh()

    def value(self):
        return self.sp.get()

    def refresh(self):
        sp = self.sp
        v = max(sp.lo, min(sp.hi, self.value()))
        x = self.x0 + (v - sp.lo) / float(sp.hi - sp.lo) * (self.x1 - self.x0)
        self.fill.setSx(max(0.001, x - self.x0))
        self.knob.setPos(x, 0, self.zt)
        self.val.setText(sp.fmt(v))
        if sp.enabled:
            self.fill.setColor(1.0, 0.62, 0.14, 1)
            self.knob.setColor(*((1.0, 1.0, 0.78, 1) if self.on else (1.0, 0.85, 0.4, 1)))
        else:
            self.fill.setColor(0.35, 0.37, 0.40, 1)
            self.knob.setColor(0.5, 0.52, 0.55, 1)

    def hit(self, ax, az):
        return self.sp.enabled and self.x0 - 0.05 <= ax <= self.x1 + 0.05 and self.zt - 0.055 <= az <= self.z + 0.06

    def set_hot(self, on):
        if on != self.on:
            self.on = on
            self.refresh()

    def follow(self, mx):
        sp = self.sp
        t = max(0.0, min(1.0, (mx - self.x0) / (self.x1 - self.x0)))
        v = round((sp.lo + t * (sp.hi - sp.lo)) / sp.step) * sp.step
        v = int(v) if isinstance(sp.step, int) else round(v, 4)
        if v != sp.get():
            sp.set_(v)
        self.refresh()

    def destroy(self):
        self.lab.destroy()
        self.val.destroy()
        self.root.removeNode()


def over_or_driving(game):
    pl = game.player
    return pl.vehicle >= 0 or pl.heli >= 0 or pl.mount >= 0


class Crosshair:
    """Fadenkreuz aus vier Strichen mit Lücke in der Mitte. Die Striche rücken beim Gehen, Rennen, Drehen,
    in der Luft und nach Schüssen auseinander (ungenauer) und ziehen sich geduckt zusammen."""
    BASE, LEN, TH = 0.014, 0.024, 0.0026

    def __init__(self, parent):
        self.root = parent.attachNewNode("crosshair")
        self.gap = self.BASE
        self.arms = []
        for dx, dz in ((-1, 0), (1, 0), (0, 1), (0, -1)):
            hold = self.root.attachNewNode("arm")
            for grow, col in ((0.0012, (0, 0, 0, 0.7)), (0.0, (1, 1, 1, 0.92))):
                if dx:
                    fr = (0.0 - grow, self.LEN + grow, -self.TH - grow, self.TH + grow)
                else:
                    fr = (-self.TH - grow, self.TH + grow, 0.0 - grow, self.LEN + grow)
                cm = CardMaker("ch")
                cm.setFrame(*fr)
                c = hold.attachNewNode(cm.generate())
                c.setColor(*col)
                c.setTransparency(TransparencyAttrib.MAlpha)
            hold.setH(0)
            self.arms.append((hold, dx, dz))
        self.root.setBin("fixed", 38)
        self.root.setDepthTest(False)
        self.root.setDepthWrite(False)
        self.place(self.gap)

    def place(self, g):
        self.gap = g
        for hold, dx, dz in self.arms:
            # links/unten: Strich beginnt bei -(Lücke+Länge), rechts/oben bei +Lücke
            ox = g if dx > 0 else (-g - self.LEN if dx < 0 else 0.0)
            oz = g if dz > 0 else (-g - self.LEN if dz < 0 else 0.0)
            hold.setPos(ox, 0, oz)

    def target(self, walk, run, turn, air, bloom, crouch, hip=0.0):
        return max(0.008, min(0.14, self.BASE + hip + 0.010 * walk + 0.018 * run + 0.026 * turn
                              + 0.022 * air + 0.012 * bloom - 0.004 * crouch))

    def update(self, dt, **k):
        t = self.target(**k)
        a = min(1.0, (22.0 if t > self.gap else 11.0) * dt)         # schnell auf, langsamer zu
        self.place(self.gap + (t - self.gap) * a)

    def show(self):
        self.root.show()

    def hide(self):
        self.root.hide()


def project_dir(cam, pt, tv):
    """Weltpunkt pt auf den Bildschirm (aspect2d-Einheiten) projizieren. cam = (x, y, z, Kurs, Nick, Roll) der
    Kamera, tv = tan(halber vertikaler Öffnungswinkel). -> (x, z) oder None, wenn der Punkt hinter der Kamera liegt."""
    cx, cy, cz, h, p, r = cam
    h, p, r = math.radians(h), math.radians(p), math.radians(r)
    f = (-math.sin(h) * math.cos(p), math.cos(h) * math.cos(p), math.sin(p))
    r0 = (math.cos(h), math.sin(h), 0.0)
    u0 = cross(r0, f)
    cr, sr = math.cos(r), math.sin(r)
    right = tuple(a * cr - b * sr for a, b in zip(r0, u0))
    up = tuple(b * cr + a * sr for a, b in zip(r0, u0))
    v = (pt[0] - cx, pt[1] - cy, pt[2] - cz)
    yc = v[0] * f[0] + v[1] * f[1] + v[2] * f[2]
    if yc < 0.5:
        return None
    return ((v[0] * right[0] + v[1] * right[1] + v[2] * right[2]) / yc / tv,
            (v[0] * up[0] + v[1] * up[1] + v[2] * up[2]) / yc / tv)


class HeliSight:
    """Fadenkreuz des Helikopters: Ring mit Punkt, wird auf den Punkt vor der Nase gesetzt."""
    R = 0.05

    def __init__(self, parent):
        self.root = parent.attachNewNode("heli_sight")
        back = self.root.attachNewNode("hs_back")
        self.fg = self.root.attachNewNode("hs_fg")
        n = 20
        bars = []
        for i in range(n):                                    # Ring aus kurzen Strichen
            a = 360.0 * i / n
            bars.append((a, self.R, 0.022, 0.0035))
        for a in (0, 90, 180, 270):                           # vier Striche nach aussen
            bars.append((a, self.R + 0.02, 0.026, 0.0028))
        for par, grow, col in ((back, 0.0016, (0, 0, 0, 0.7)), (self.fg, 0.0, (0.6, 1.0, 0.6, 0.95))):
            for a, rad, ln, th in bars:
                h = par.attachNewNode("s")
                h.setR(a)
                cm = CardMaker("hs")
                cm.setFrame(rad - ln / 2 - grow, rad + ln / 2 + grow, -th - grow, th + grow)
                c = h.attachNewNode(cm.generate())
                c.setColor(*col)
                c.setTransparency(TransparencyAttrib.MAlpha)
            cm = CardMaker("hs_dot")
            cm.setFrame(-0.004 - grow, 0.004 + grow, -0.004 - grow, 0.004 + grow)
            c = par.attachNewNode(cm.generate())
            c.setColor(*col)
            c.setTransparency(TransparencyAttrib.MAlpha)
        self.root.setBin("fixed", 37)
        self.root.setDepthTest(False)
        self.root.setDepthWrite(False)

    def place(self, x, z):
        self.root.setPos(x, 0, z)

    def show(self):
        self.root.show()

    def hide(self):
        self.root.hide()


